:root {
  --sand: #f5c842;
  --ocean: #1a7abf;
  --white: #ffffff;
  --dark: #1c2b3a;
  --win-green: #2ec46e;
  --muted: #6b8099;
  --live-red: #e8394a;
  --card-bg: #ffffff;
}

.bracket-card {
  background: var(--card-bg);
  border: 2px solid var(--ocean);
  border-radius: 16px;
  width: 340px;
  padding: 0;
  overflow: hidden;
}

.bracket-header {
  background: var(--ocean);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.bracket-icon {
  font-size: 22px;
  line-height: 1;
}

.bracket-title {
  flex: 1;
}

.bracket-title h1 {
  font-size: 15px;
  font-weight: 700;
  color: var(--white);
  margin: 0;
  line-height: 1.2;
}

.bracket-subtitle {
  font-size: 11px;
  color: var(--sand);
  margin: 0;
  line-height: 1.4;
}

.bracket-badge {
  background: var(--live-red);
  color: var(--white);
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  letter-spacing: 0.08em;
}

.bracket-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.match {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #f0f5fa;
  border-radius: 10px;
  padding: 10px 14px;
  border: 1.5px solid transparent;
}

.match--winner {
  border-color: var(--win-green);
  background: #edfaf3;
}

.team {
  font-size: 13px;
  font-weight: 600;
  color: var(--dark);
}

.score {
  font-size: 18px;
  font-weight: 700;
  color: var(--muted);
  min-width: 28px;
  text-align: right;
}

.score--win {
  color: var(--win-green);
}

.bracket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1.5px solid #e2eaf2;
}

.court {
  font-size: 12px;
  color: var(--muted);
  font-weight: 500;
}

.round-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--ocean);
}
